-- Phase 90: Enterprise Architecture (relationship and governance control plane)
create type public.architecture_context_type as enum('masterapp_platform_architecture','tenant_business_architecture');
create type public.architecture_relation_state as enum('current','target');
create type public.architecture_evidence_status as enum('candidate','confirmed','rejected','historical');

create table public.architecture_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permission_key text not null,granted_at timestamptz not null default now(),unique(organization_id,user_id,permission_key));
create table public.business_capabilities(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,capability_key text not null,name text not null,description text not null default '',level smallint not null check(level between 1 and 4),parent_id uuid references public.business_capabilities(id) on delete restrict,domain text not null,criticality text not null default 'medium' check(criticality in('low','medium','high','critical')),strategic_importance text not null default 'medium',owner_ref text,status text not null default 'draft' check(status in('draft','active','deprecated','retired')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((context_type='tenant_business_architecture' and organization_id is not null)or(context_type='masterapp_platform_architecture' and organization_id is null)),unique(context_type,organization_id,capability_key));
create table public.architecture_applications(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,application_key text not null,name text not null,description text not null default '',application_type text not null default 'business_application',domain text not null,provider_name text,source_ref_type text,source_ref_id text,system_of_record boolean not null default false,business_criticality text not null default 'medium',lifecycle_status text not null default 'active' check(lifecycle_status in('planned','active','deprecated','retirement_candidate','retired')),lifecycle_target_date date,owner_ref text,technology_stack jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((context_type='tenant_business_architecture' and organization_id is not null)or(context_type='masterapp_platform_architecture' and organization_id is null)),unique(context_type,organization_id,application_key));
create unique index architecture_applications_source_ref_unique on public.architecture_applications(context_type,organization_id,source_ref_type,source_ref_id) where source_ref_id is not null;
create table public.architecture_ownership(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,entity_type text not null,entity_id text not null,owner_type text not null check(owner_type in('business','technical','data','security','operations')),owner_ref text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(context_type,organization_id,entity_type,entity_id,owner_type));
create table public.architecture_relationship_types(id uuid primary key default gen_random_uuid(),relationship_key text not null unique,name text not null,description text not null default '',allowed_source_types text[] not null,allowed_target_types text[] not null,directional boolean not null default true,critical_change boolean not null default false,active boolean not null default true,created_at timestamptz not null default now());
create table public.architecture_relationships(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,relationship_type_id uuid not null references public.architecture_relationship_types(id) on delete restrict,source_entity_type text not null,source_entity_id text not null,target_entity_type text not null,target_entity_id text not null,relation_state public.architecture_relation_state not null default 'current',evidence_status public.architecture_evidence_status not null default 'candidate',source_kind text not null check(source_kind in('manual','deterministic_reconciliation','declared_manifest','inferred','imported')),source_ref text,confidence numeric(4,3) not null default 0.5 check(confidence between 0 and 1),valid_from timestamptz not null default now(),valid_until timestamptz,metadata jsonb not null default '{}',created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((context_type='tenant_business_architecture' and organization_id is not null)or(context_type='masterapp_platform_architecture' and organization_id is null)),unique(context_type,organization_id,relationship_type_id,source_entity_type,source_entity_id,target_entity_type,target_entity_id,relation_state));
create table public.architecture_adjacency(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,relationship_id uuid not null references public.architecture_relationships(id) on delete cascade,from_type text not null,from_id text not null,to_type text not null,to_id text not null,relation_state public.architecture_relation_state not null,evidence_status public.architecture_evidence_status not null,refreshed_at timestamptz not null default now(),unique(relationship_id,from_type,from_id,to_type,to_id));
create table public.architecture_assessments(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,entity_type text not null,entity_id text not null,assessment_type text not null,dimensions jsonb not null check(jsonb_typeof(dimensions)='object'),evidence jsonb not null default '{}',assessed_by uuid references auth.users(id) on delete set null,assessed_at timestamptz not null default now(),valid_until timestamptz,opaque_score boolean not null default false);
create table public.technology_components(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,component_key text not null,name text not null,component_type text not null,provider_name text,version text,lifecycle_status text not null default 'active',support_end_date date,standard_status text not null default 'assess',owner_ref text,source_asset_id uuid references public.assets(id) on delete set null,created_at timestamptz not null default now(),unique(context_type,organization_id,component_key));
create table public.architecture_standards(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,standard_key text not null,name text not null,description text not null,scope jsonb not null default '{}',status text not null default 'draft' check(status in('draft','published','deprecated','retired')),version integer not null default 1,effective_from date,effective_until date,owner_ref text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(context_type,organization_id,standard_key,version));
create table public.architecture_decisions(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,decision_key text not null,title text not null,context text not null,decision text not null,alternatives jsonb not null default '[]',consequences jsonb not null default '[]',status text not null default 'draft' check(status in('draft','proposed','accepted','rejected','superseded')),supersedes_id uuid references public.architecture_decisions(id) on delete restrict,owner_ref text not null,accepted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(context_type,organization_id,decision_key));
create table public.architecture_decision_addenda(id uuid primary key default gen_random_uuid(),decision_id uuid not null references public.architecture_decisions(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,addendum text not null,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.architecture_exceptions(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,standard_id uuid not null references public.architecture_standards(id) on delete restrict,entity_type text not null,entity_id text not null,reason text not null,compensating_controls jsonb not null default '[]',status text not null default 'requested' check(status in('requested','approved','rejected','expired','revoked')),expires_at timestamptz not null,approved_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.architecture_reviews(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,scope jsonb not null,review_type text not null,status text not null default 'requested',due_at timestamptz,owner_ref text,project_ref text,change_ref text,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.architecture_review_findings(id uuid primary key default gen_random_uuid(),review_id uuid not null references public.architecture_reviews(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,finding_type text not null,severity text not null,title text not null,evidence jsonb not null default '{}',status text not null default 'open',created_at timestamptz not null default now());
create table public.target_architecture_states(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,description text not null default '',target_date date,status text not null default 'draft',baseline_snapshot_id uuid,approved_at timestamptz,created_at timestamptz not null default now());
create table public.architecture_roadmaps(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,description text not null default '',target_state_id uuid references public.target_architecture_states(id) on delete set null,status text not null default 'draft',owner_ref text not null,start_date date,target_date date,created_at timestamptz not null default now());
create table public.architecture_roadmap_items(id uuid primary key default gen_random_uuid(),roadmap_id uuid not null references public.architecture_roadmaps(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,title text not null,item_type text not null,entity_type text,entity_id text,project_ref text,change_ref text,risk_ref text,status text not null default 'planned',starts_on date,ends_on date,sequence_no integer not null default 0,created_at timestamptz not null default now());
create table public.architecture_technical_debt(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,title text not null,description text not null,category text not null,severity text not null,entity_type text not null,entity_id text not null,evidence jsonb not null default '{}',status text not null default 'open',owner_ref text,project_ref text,change_ref text,risk_ref text,created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.architecture_modernization_opportunities(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,title text not null,opportunity_type text not null,entity_type text not null,entity_id text not null,finding text not null,evidence jsonb not null,confidence text not null check(confidence in('low','medium','high')),status text not null default 'candidate',project_draft_ref text,change_draft_ref text,auto_execute boolean not null default false,created_at timestamptz not null default now());
create table public.architecture_analysis_runs(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,analysis_type text not null,root_entity_type text not null,root_entity_id text not null,relation_state public.architecture_relation_state not null,max_depth smallint not null default 4 check(max_depth between 1 and 8),max_nodes integer not null default 500 check(max_nodes between 1 and 5000),status text not null default 'queued',method_version text not null default 'ea-graph-v1',result_summary jsonb not null default '{}',created_at timestamptz not null default now(),completed_at timestamptz);
create table public.architecture_analysis_jobs(id uuid primary key default gen_random_uuid(),analysis_run_id uuid not null references public.architecture_analysis_runs(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,status text not null default 'queued',attempt_count integer not null default 0,available_at timestamptz not null default now(),lease_expires_at timestamptz,created_at timestamptz not null default now());
create table public.architecture_snapshots(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,snapshot_type text not null default 'baseline',scope jsonb not null,content_hash text not null,entity_counts jsonb not null,relationship_counts jsonb not null,source_versions jsonb not null,immutable_payload jsonb not null,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(context_type,organization_id,content_hash));
alter table public.target_architecture_states add constraint target_architecture_baseline_fk foreign key(baseline_snapshot_id) references public.architecture_snapshots(id) on delete set null;
create table public.architecture_drift_candidates(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,entity_type text not null,entity_id text not null,drift_type text not null,source_ref text not null,expected_value jsonb,observed_value jsonb,evidence jsonb not null default '{}',confidence text not null,status text not null default 'candidate',detected_at timestamptz not null default now(),resolved_at timestamptz);
create table public.architecture_reconciliation_runs(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,source_type text not null,status text not null default 'queued',created_count integer not null default 0,updated_count integer not null default 0,candidate_count integer not null default 0,manual_metadata_preserved boolean not null default true,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table public.architecture_audit_events(id uuid primary key default gen_random_uuid(),context_type public.architecture_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id) on delete set null,action text not null,resource_type text not null,resource_id text,correlation_id text,safe_metadata jsonb not null default '{}',created_at timestamptz not null default now());

create function public.prevent_accepted_adr_rewrite() returns trigger language plpgsql set search_path=public as $$begin if old.status in('accepted','superseded') and (new.title,new.context,new.decision,new.alternatives,new.consequences) is distinct from (old.title,old.context,old.decision,old.alternatives,old.consequences) then raise exception 'ACCEPTED_ADR_IMMUTABLE'; end if; return new; end$$;
create trigger architecture_decisions_immutable before update on public.architecture_decisions for each row execute function public.prevent_accepted_adr_rewrite();

insert into public.architecture_relationship_types(relationship_key,name,allowed_source_types,allowed_target_types,critical_change) values
('capability_parent','Capability hierarchy','{capability}','{capability}',false),('capability_process','Capability supported by process','{capability}','{process}',false),('capability_application','Capability supported by application','{capability}','{application}',false),('application_service','Application uses service','{application}','{service}',false),('application_data','Application uses data asset','{application}','{data_asset}',true),('application_integration','Application uses integration','{application}','{integration}',false),('application_technology','Application uses technology','{application}','{technology}',false),('system_of_record','System of record','{application}','{capability,data_asset}',true),('depends_on','Depends on','{capability,application,service,process,integration,technology}','{capability,application,service,process,integration,technology,data_asset}',false),('replaces','Replaces','{application,service,technology}','{application,service,technology}',false) on conflict(relationship_key) do nothing;

-- quality: allow-nonconcurrent-index reason=new-empty-enterprise-architecture-tables
create index architecture_capabilities_tree_idx on public.business_capabilities(context_type,organization_id,parent_id,level,status);
create index architecture_applications_portfolio_idx on public.architecture_applications(context_type,organization_id,lifecycle_status,business_criticality);
create index architecture_relationships_source_idx on public.architecture_relationships(context_type,organization_id,source_entity_type,source_entity_id,relation_state,evidence_status);
create index architecture_relationships_target_idx on public.architecture_relationships(context_type,organization_id,target_entity_type,target_entity_id,relation_state,evidence_status);
create index architecture_adjacency_from_idx on public.architecture_adjacency(context_type,organization_id,from_type,from_id,relation_state,evidence_status);
create index architecture_jobs_queue_idx on public.architecture_analysis_jobs(status,available_at,lease_expires_at);
create index architecture_drift_open_idx on public.architecture_drift_candidates(context_type,organization_id,status,detected_at desc);
create index architecture_audit_lookup_idx on public.architecture_audit_events(context_type,organization_id,created_at desc);

create view public.enterprise_architecture_overview with(security_invoker=true) as select context_type,organization_id,(select count(*) from public.business_capabilities c where c.context_type=a.context_type and c.organization_id is not distinct from a.organization_id and c.status='active') active_capabilities,count(*) filter(where lifecycle_status<>'retired') applications,count(*) filter(where lifecycle_status='deprecated') deprecated_applications,count(*) filter(where owner_ref is null) unowned_applications from public.architecture_applications a group by context_type,organization_id;

do $$declare t text;begin foreach t in array array['architecture_member_permissions','business_capabilities','architecture_applications','architecture_ownership','architecture_relationship_types','architecture_relationships','architecture_adjacency','architecture_assessments','technology_components','architecture_standards','architecture_decisions','architecture_decision_addenda','architecture_exceptions','architecture_reviews','architecture_review_findings','target_architecture_states','architecture_roadmaps','architecture_roadmap_items','architecture_technical_debt','architecture_modernization_opportunities','architecture_analysis_runs','architecture_analysis_jobs','architecture_snapshots','architecture_drift_candidates','architecture_reconciliation_runs','architecture_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on public.enterprise_architecture_overview from public,anon,authenticated;grant select on public.enterprise_architecture_overview to service_role;

insert into public.feature_definitions(feature_key,name,description,category,value_type,default_value,safe_default,client_safe,owner_label,lifecycle_status,created_at,updated_at) values
('enterprise_architecture_enabled','Enterprise Architecture','Ativa o control plane de arquitetura empresarial.','governance','boolean','false','false',false,'Enterprise Architecture','active',now(),now()),('business_capability_management_enabled','Business Capability Management','Ativa hierarquia e avaliações de capacidades.','governance','boolean','false','false',false,'Enterprise Architecture','active',now(),now()),('architecture_dependency_graph_enabled','Architecture Dependency Graph','Ativa grafo tipado e travessias limitadas.','governance','boolean','false','false',false,'Enterprise Architecture','active',now(),now()),('architecture_modernization_enabled','Architecture Modernization','Ativa roadmaps, dívida e oportunidades sem execução automática.','governance','boolean','false','false',false,'Enterprise Architecture','active',now(),now()) on conflict(feature_key) do update set name=excluded.name,description=excluded.description,updated_at=now();

insert into public.workspace_widget_registry(id,title,description,category,widget_type,required_permissions,supported_scopes,data_source,refresh_strategy,configuration_schema,default_settings,route,display_safe,sensitive) values
('critical_capability_gaps','Critical Capability Gaps','Lacunas de capacidades críticas.','governance','status_list','{architecture:view_capabilities}','{organization}','architecture:capability_gaps','5m','{}','{}','/painel/governanca/arquitetura?tab=Capacidades',false,true),('architecture_risks','Architecture Risks','Exposição arquitetural associada a riscos.','governance','status_list','{architecture:view}','{organization}','architecture:risks','5m','{}','{}','/painel/governanca/arquitetura',false,true),('deprecated_systems','Deprecated Systems','Sistemas depreciados ainda em uso.','governance','status_list','{architecture:view_applications}','{organization}','architecture:deprecated','5m','{}','{}','/painel/governanca/arquitetura?tab=Aplicações',false,true),('architecture_technical_debt','Technical Debt','Dívida técnica arquitetural em aberto.','governance','status_list','{architecture:manage_technical_debt}','{organization}','architecture:debt','5m','{}','{}','/painel/governanca/arquitetura?tab=Technical%20Debt',false,true),('single_dependency_exposure','Single Dependency Exposure','Dependências únicas confirmadas.','governance','metric_card','{architecture:view_dependencies}','{organization}','architecture:single_dependency','5m','{}','{}','/painel/governanca/arquitetura?tab=Dependências',false,true),('architecture_reviews_due','Architecture Reviews Due','Revisões de arquitetura vencidas ou próximas.','governance','status_list','{architecture:manage_governance}','{organization}','architecture:reviews_due','5m','{}','{}','/painel/governanca/arquitetura',false,true),('modernization_initiatives','Modernization Initiatives','Iniciativas de modernização ativas.','governance','status_list','{architecture:manage_roadmaps}','{organization}','architecture:modernization','5m','{}','{}','/painel/governanca/arquitetura?tab=Roadmaps',false,true) on conflict(id) do update set title=excluded.title,description=excluded.description,data_source=excluded.data_source,route=excluded.route,active=true,updated_at=now();
